C++17 added std::string_view — a non-owning view into a string. Use for function parameters when you don't need to own/modify:
#include <string_view>
void print(std::string_view sv) { // takes string, char*, literal, etc.
std::cout << sv << "\n";
}

The single most underused header. Replaces hand-written loops with descriptive, optimised one-liners.
#include <algorithm>
#include <numeric> // accumulate
#include <vector>
std::vector<int> v{5, 2, 8, 1, 9, 3};
// sort
std::sort(v.begin(), v.end()); // ascending
std::sort(v.begin(), v.end(), std::greater{}); // descending
// find
auto it = std::find(v.begin(), v.end(), 8);
if (it != v.end()) { /* found */ }
// count
int n_evens = std::count_if(v.begin(), v.end(), [](int x){ return x % 2 == 0; });
// sum
int total = std::accumulate(v.begin(), v.end(), 0);
// transform
std::vector<int> squares(v.size());
std::transform(v.begin(), v.end(), squares.begin(), [](int x){ return x * x; });
// for_each
std::for_each(v.begin(), v.end(), [](int x){ std::cout << x << " "; });
// any / all / none of
bool has_neg = std::any_of(v.begin(), v.end(), [](int x){ return x < 0; });
bool all_pos = std::all_of(v.begin(), v.end(), [](int x){ return x > 0; });
// min / max element
auto mn = std::min_element(v.begin(), v.end());
auto mx = std::max_element(v.begin(), v.end());
// reverse
std::reverse(v.begin(), v.end());
// unique (after sort)
std::sort(v.begin(), v.end());
auto last = std::unique(v.begin(), v.end());
v.erase(last, v.end());
Trick: before writing a loop on a container, search cppreference's algorithm list — there's almost always a standard one.

auto is_even = [](int x){ return x % 2 == 0; };
auto add = [](int a, int b){ return a + b; };
// with capture
int threshold = 10;
auto over = [threshold](int x){ return x > threshold; };
// capture by reference
int count = 0;
std::for_each(v.begin(), v.end(), [&count](int){ ++count; });
[ ] is the capture list. [=] captures everything by value, [&] by reference. Be explicit when possible.

C++20 introduced ranges — algorithms that take the container directly + composable views.
#include <ranges>
#include <vector>
#include <algorithm>
std::vector<int> v{1, 2, 3, 4, 5, 6};
// pipeline
auto result = v
| std::views::filter([](int x){ return x % 2 == 0; })
| std::views::transform([](int x){ return x * x; });
for (int x : result) std::cout << x << " "; // 4 16 36
// direct algorithm
std::ranges::sort(v); // no begin()/end() needed!
Cleaner than iterator-pair style. Worth learning if your compiler supports C++20.

