Read words from stdin until EOF; print each unique word and its count, sorted by count descending.
Solution sketch
#include <iostream>
#include <unordered_map>
#include <vector>
#include <algorithm>
#include <string>
int main() {
std::unordered_map<std::string, int> counts;
std::string w;
while (std::cin >> w) counts[w]++;
std::vector<std::pair<std::string, int>> sorted(counts.begin(), counts.end());
std::sort(sorted.begin(), sorted.end(),
[](auto& a, auto& b){ return a.second > b.second; });
for (const auto& [word, n] : sorted) {
std::cout << word << ": " << n << "\n";
}
}

Given std::vector<int>, return the sum of squares of even values. Use STL only — no manual loop.
Solution
int sum_sq_even(const std::vector<int>& v) {
return std::accumulate(v.begin(), v.end(), 0,
[](int acc, int x){ return x % 2 == 0 ? acc + x * x : acc; });
}

Given std::vector<int>, return a std::vector<int> of values that appear more than once (each duplicate listed once).
Solution sketch
std::vector<int> dups(const std::vector<int>& v) {
std::unordered_map<int, int> count;
for (int x : v) count[x]++;
std::vector<int> r;
for (const auto& [k, n] : count) if (n > 1) r.push_back(k);
return r;
}
